def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) < 2:
        raise Blocked("need at least two communities")
    return statusCode == 200 and responseBody.get("code") == 0 and all(item.get("id") and item.get("name") for item in data) and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data") or {}
    return statusCode == 200 and responseBody.get("code") == 0 and bool(data.get("accessToken")) and bool(data.get("refreshToken")) and isinstance(data.get("user"), dict) and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
